def configure(deck):
    """Tell the policy which pre-evolutions our deck can actually use."""
    EVOLVES_FROM_IN_DECK.clear()
    for cid in set(deck):
        c = CARDS.get(cid)
        if c and c.get("evolvesFrom"):
            EVOLVES_FROM_IN_DECK.add(c["evolvesFrom"])
    if playbook is not None:
        try:
            playbook.configure(deck)
        except Exception:
            pass

def _get(o, k, d=None):
    if isinstance(o, dict):
        return o.get(k, d)
    return getattr(o, k, d)

def _ov_set():
    try:
        v = os.environ.get("PILOT_OV")
        if v is None or v == "":
            v = DEFAULT_OV
        return frozenset(x.strip() for x in v.split(",") if x.strip())
    except Exception:
        return frozenset(DEFAULT_OV.split(","))

def _sha256(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()

def _clean(ax, xgrid=False, ygrid=False):
    ax.tick_params(length=0)
    if xgrid:
        ax.xaxis.grid(True, color=GRID, lw=0.8)
    if ygrid:
        ax.yaxis.grid(True, color=GRID, lw=0.8)
    ax.set_axisbelow(True)
